import {BombGame} from './bomb-engine.js';
import {loadWords} from './word-store.js';
import {readWords} from './vocab.js';
import {bindGameLifecycle} from './game-lifecycle.js';
const $=id=>document.getElementById(id);let game=null,paused=false,last=0,previous='',shownRound=0,shownResult=false,muted=true,audio=null;
function tone(f){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.45,audio.currentTime+.16);g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.2);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.21);}catch{}}
function start(){try{const p=readWords(loadWords());if(p.errors.length)throw Error(p.errors[0]);game=new BombGame(p.entries);}catch(e){$('error').textContent=e.message;return;}paused=false;shownRound=0;shownResult=false;previous='';for(const id of['intro','result','pauseScreen','roundScreen'])$(id).classList.add('hidden');last=performance.now();render();}
function pause(value){if(!game||['done','round'].includes(game.phase))return;paused=value;$('pauseScreen').classList.toggle('hidden',!value);render();}
function answer(value){if(paused||!game)return;const ok=game.answer(value);if(ok!==null)tone(ok?720:150);render();}
function render(){if(!game)return;const g=game;$('round').textContent='ROUND '+g.round;$('youStars').textContent='★'.repeat(g.stars[0])+'☆'.repeat(3-g.stars[0]);$('cpuStars').textContent='★'.repeat(g.stars[1])+'☆'.repeat(3-g.stars[1]);$('seconds').textContent=g.fuse.toFixed(1)+'s';$('fuseBar').style.width=g.fuse/g.total*100+'%';$('bomb').classList.toggle('cpu-side',g.owner===1);$('arena').classList.toggle('danger',g.fuse<5&&g.phase!=='round'&&g.phase!=='done');$('boom').classList.toggle('hidden',g.phase!=='round');$('bomb').classList.toggle('hidden',g.phase==='round'||g.phase==='done');$('yes').disabled=$('no').disabled=paused||g.phase!=='player';$('score').textContent=g.score.toLocaleString()+' pts';$('combo').textContent='連続正解 '+g.streak;
 let status='';if(g.phase==='ready')status=`${Math.ceil(g.delay)}… ${g.owner===0?'あなた':'CPU'}からスタート！`;else if(g.phase==='player')status='あなたの番！ ○か×でパス！';else if(g.phase==='wrong')status='不正解！ まだ手元にある！';else if(g.phase==='pass')status='ナイスパス！';else if(g.phase==='cpu')status='CPUが考え中…';else if(g.phase==='cpuWrong')status='CPUが間違えた！ チャンス！';else status=g.feedback;if(status!==previous){$('status').textContent=status;previous=status;}
 const active=['player','wrong'].includes(g.phase);$('question').classList.toggle('waiting',!active);$('questionLabel').textContent=active?'登録した単語と訳の組み合わせ、合ってる？':'導火線は止まらない！';$('word').textContent=active?g.q.entry.word:g.phase==='ready'?'READY?':g.phase==='round'?'BOOM!':'CPUの番';$('meaning').textContent=active?g.q.meaning:g.phase==='ready'?'落ち着いて単語を見よう':g.phase==='pass'?'爆弾をパス！':'次に渡ってきたら、すばやく答えよう';$('feedback').textContent=g.phase==='wrong'?'正しい組：'+g.feedback:g.phase==='player'?'○＝合ってる ／ ×＝ちがう':'CPUも同じ導火線で勝負しています。';
 if(g.phase==='round'&&shownRound!==g.round){shownRound=g.round;tone(80);$('roundKicker').textContent=g.boomOwner===1?'YOU GET A STAR!':'CPU GETS A STAR';$('roundTitle').textContent=g.feedback;$('roundStars').textContent=g.stars[0]+' − '+g.stars[1];$('roundDetail').textContent='あなた '+g.stars[0]+'★ ／ CPU '+g.stars[1]+'★';$('next').textContent=g.stars.some(n=>n>=3)?'結果を見る':'次のラウンド！';$('roundScreen').classList.remove('hidden');}
 if(g.phase==='done'&&!shownResult){shownResult=true;$('resultKicker').textContent=g.win?'YOU WIN!':'NEXT TIME!';$('resultTitle').textContent=g.win?'爆弾リレー、勝利！':'もう一度リベンジ！';$('resultScore').textContent=g.stars[0]+' − '+g.stars[1];$('resultStats').textContent=`${g.score}点 · ${g.answered}問中${g.correct}問正解 · 最大${g.bestStreak}連続`;$('review').replaceChildren();for(const p of g.review.values()){const div=document.createElement('div'),b=document.createElement('b');b.textContent=p.word;div.append(b,document.createTextNode(' — '+p.meaning));$('review').append(div);}$('reviewSection').classList.toggle('hidden',!g.review.size);$('result').classList.remove('hidden');}}
$('start').onclick=start;$('again').onclick=start;$('yes').onclick=()=>answer(true);$('no').onclick=()=>answer(false);$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);$('next').onclick=()=>{if(game?.continue()){$('roundScreen').classList.add('hidden');render();}};$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'音 OFF':'音 ON';tone(650);};bindGameLifecycle(window,document,{pause});window.addEventListener('keydown',e=>{if(e.repeat)return;if(e.key==='Escape')pause(!paused);if(e.key==='ArrowLeft'){e.preventDefault();answer(true);}if(e.key==='ArrowRight'){e.preventDefault();answer(false);}});
function frame(t){const dt=last?Math.min((t-last)/1000,.1):0;last=t;if(game&&!paused&&!document.hidden&&!['round','done'].includes(game.phase)){game.tick(dt);render();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
